import os
import re

EXCLUDES = [".pio", ".git", ".agents", "third_party", "vendor", "stubs", "tmp", "test", "tests"]

def is_excluded(path):
    return any(x in path for x in EXCLUDES)

classes = {}

for root, dirs, files in os.walk("."):
    if is_excluded(root): continue
    for f in files:
        if f.endswith((".hpp", ".h")):
            path = os.path.join(root, f)
            with open(path, errors="ignore") as fp:
                lines = fp.readlines()

            in_class = None
            vis = "private"
            brace_depth = 0
            class_brace = 0

            for lno, line in enumerate(lines, 1):
                # Check for class start
                m = re.search(r'\bclass\s+([A-Za-z0-9_]+)', line)
                if m and not line.strip().endswith(";") and "enum class" not in line:
                    in_class = m.group(1)
                    vis = "private"
                    class_brace = brace_depth

                if in_class:
                    if "public:" in line: vis = "public"
                    elif "protected:" in line: vis = "protected"
                    elif "private:" in line: vis = "private"
                    else:
                        stripped = line.strip()
                        # Ignore inner structs or unions or classes
                        if stripped.startswith("struct ") or stripped.startswith("class ") or stripped.startswith("union ") or stripped.startswith("enum "):
                            pass
                        elif (stripped.endswith(";") and not "(" in stripped and
                              not stripped.startswith(("//", "/*", "*", "using", "typedef", "friend", "static constexpr", "return", "namespace", "template", "#"))):
                            # clean line
                            clean = re.sub(r"//.*$", "", stripped).rstrip(";").strip()
                            clean = re.sub(r"=.*$", "", clean).strip()
                            clean = re.sub(r"\{.*\}$", "", clean).strip()
                            parts = clean.split()
                            if parts:
                                vname = parts[-1].lstrip("*&")
                                vname = re.sub(r"\[.*\]", "", vname).strip()
                                if vname and vname != "}":
                                    classes.setdefault(f"{path}::{in_class}", []).append((vis, vname, lno, line.strip()))

                brace_depth += line.count("{") - line.count("}")
