import os
import re

EXCLUDES = [".pio", ".git", ".agents", "third_party", "vendor", "stubs", "tmp", "test", "tests"]

def is_excluded(path):
    return any(x in path for x in EXCLUDES)

def clean_code(text):
    # Remove block comments
    text = re.sub(r'/\*[\s\S]*?\*/', '', text)
    # Remove line comments
    text = re.sub(r'//.*', '', text)
    return text

files = []
for root, dirs, files_in_dir in os.walk("."):
    if is_excluded(root): continue
    for f in files_in_dir:
        if f.endswith((".hpp", ".h")):
            files.append(os.path.join(root, f))

for p in sorted(files):
    with open(p, errors="ignore") as fp:
        raw_lines = fp.readlines()

    # Track multi-line comment state
    in_block_comment = False
    in_class = None
    vis = "private"
    class_brace = 0
    brace_depth = 0

    for lno, line in enumerate(raw_lines, 1):
        s = line.strip()
        # Handle block comments
        if in_block_comment:
            if "*/" in s:
                in_block_comment = False
                s = s[s.index("*/")+2:].strip()
            else:
                continue
        if "/*" in s:
            if "*/" in s:
                s = re.sub(r'/\*.*?\*/', '', s).strip()
            else:
                in_block_comment = True
                s = s[:s.index("/*")].strip()

        # Remove line comments
        s = re.sub(r'//.*', '', s).strip()
        if not s:
            continue

        # Look for class definition
        m_cls = re.search(r'\bclass\s+([A-Za-z0-9_]+)\b', s)
        if m_cls and not s.endswith(';') and "enum class" not in s:
            in_class = m_cls.group(1)
            vis = "private"
            class_brace = brace_depth

        if in_class:
            if s.startswith("public:"):
                vis = "public"
            elif s.startswith("protected:"):
                vis = "protected"
            elif s.startswith("private:"):
                vis = "private"
            elif vis in ("private", "protected"):
                # Check for member variable
                # Must end with ;, not contain (, not typedef/using/friend/static constexpr
                if (s.endswith(";") and "(" not in s and 
                    not s.startswith("typedef") and not s.startswith("using") and
                    not s.startswith("friend") and not s.startswith("static constexpr") and
                    not s.startswith("struct") and not s.startswith("class") and
                    not s.startswith("enum") and not s.startswith("return") and
                    not s.startswith("template") and not s.startswith("#")):

                    # May have multiple variables like: int x, y;
                    # Strip = initializer
                    clean = re.sub(r'=.*?(?=,|$|;)', '', s).rstrip(';').strip()
                    clean = re.sub(r'\{.*?\}(?=,|$|;)', '', clean).strip()
                    tokens = clean.split()
                    if len(tokens) >= 2:
                        type_tokens = tokens[:-1]
                        var_tokens = tokens[-1].split(',')
                        # If there were commas like "int x, y", tokens could be ['int', 'x,', 'y']
                        all_vars = []
                        for tok in tokens[1:]:
                            for sub in tok.split(','):
                                sub = sub.strip().lstrip('*&')
                                sub = re.sub(r'\[.*?\]', '', sub).strip()
                                if sub and sub not in ("const", "volatile", "unsigned", "signed", "long", "short"):
                                    all_vars.append(sub)
                        for v in all_vars:
                            if not v.startswith('_'):
                                print(f"{p}:{lno} [{in_class} ({vis})] {v}  --> {raw_lines[lno-1].strip()}")

        brace_depth += s.count('{') - s.count('}')
        if in_class and brace_depth <= class_brace and '}' in s:
            in_class = None

