131: /**
132:  * @brief Follow HTTP redirects and return the final response code.
133:  *
134:  * Loops up to kMaxRedirects times. Each iteration opens a new HTTP request
135:  * with download headers (User-Agent, Cache-Control, Accept,
136:  * Authorization) and disables auto-redirect to
137:  * manually follow 301/302/307/308 responses via the Location header.
138:  *
139:  * Uses HTTP/1.0 to avoid chunked transfer encoding complications on
140:  * constrained devices.
141:  *
142:  * @param client Active WiFiClient reference.
143:  * @param http   HTTPClient instance to use for requests.
144:  * @param url    Initial URL to fetch.
145:  * @param token  Optional GitHub access token.
146:  * @return HTTP status code on success, or -1 on redirect exhaustion/failure.
147:  */
148: int OTADownloadEngine::followRedirects(WiFiClient& client, HTTPClient& http,
149:                                         const std::string& url, const std::string& token) {
150:     std::string currentUrl = url;
151:     String initialHost = extractHost(url);
152: 
153:     for (int hop = 0; hop < kMaxRedirects; hop++) {
154:         // --- Begin HTTP request for this hop ---
155:         if (!http.begin(client, String(currentUrl.c_str()))) {
156:             ESP_LOGE(TAG, "http.begin() failed for URL: %s", currentUrl.c_str());
157:             return -1;
158:         }
159: 
160:         // Configure headers for GitHub release asset API
161:         http.useHTTP10(true);
162:         http.setTimeout(httpTimeout_);
163:         http.setFollowRedirects(HTTPC_DISABLE_FOLLOW_REDIRECTS);
164:         http.setUserAgent("ESP32-http-Update");
165:         http.addHeader("Cache-Control", "no-cache");
166:         http.addHeader("Accept", "application/octet-stream");
167: 
168:         String currentHost = extractHost(currentUrl);
169:         if (!token.empty() && currentHost.length() > 0 && currentHost == initialHost) {
170:             http.addHeader("Authorization", String(("Bearer " + token).c_str()));
171:         }
172: 
173:         int code = http.GET();
174: 
175:         // --- Check for redirect responses ---
176:         if (code == HTTP_CODE_MOVED_PERMANENTLY  || code == HTTP_CODE_FOUND ||
177:             code == HTTP_CODE_TEMPORARY_REDIRECT || code == HTTP_CODE_PERMANENT_REDIRECT) {
178:             String newUrl = http.getLocation();
179:             http.end();
180: 
181:             if (newUrl.length() == 0) {
182:                 ESP_LOGE(TAG, "Redirect response but empty Location header at hop %d", hop + 1);
183:                 return -1;
184:             }
185: 
186:             ESP_LOGD(TAG, "Redirect hop %d/%d → %s", hop + 1, kMaxRedirects, newUrl.c_str());
187:             currentUrl = newUrl.c_str();
188:             continue;
189:         }
190: 
191:         // --- Non-redirect response: return the code with connection open ---
192:         return code;
193:     }
194: 
195:     // Exhausted all redirect hops
196:     ESP_LOGE(TAG, "Exceeded maximum redirect hops (%d)", kMaxRedirects);
197:     return -1;
198: }
