213: size_t OTADownloadEngine::fetchSignature(WiFiClient& client, const std::string& sigUrl,
214:                                           const std::string& token, uint8_t* sigBuf, size_t sigBufSize) {
215:     ESP_LOGI(TAG, "Fetching signature from: %s", sigUrl.c_str());
216:     HTTPClient http;
217: 
218:     int code = followRedirects(client, http, sigUrl, token);
219:     int contentLen = http.getSize();
220: 
221:     // --- Validate HTTP response ---
222:     if (code != HTTP_CODE_OK || contentLen <= 0 || static_cast<size_t>(contentLen) > sigBufSize) {
223:         ESP_LOGE(TAG, "Signature fetch failed — HTTP %d, Content-Length: %d", code, contentLen);
224:         http.end();
225:         lastError_ = OTAError::SignatureFetchFailed;
226:         return 0;
227:     }
228: 
229:     // --- Read signature bytes with timeout guard ---
230:     WiFiClient* tcp = http.getStreamPtr();
231:     size_t bytesRead = 0;
232:     unsigned long timeout = millis() + httpTimeout_;
233: 
234:     while (bytesRead < static_cast<size_t>(contentLen) && millis() < timeout) {
235:         if (tcp->available()) {
236:             int r = tcp->readBytes(sigBuf + bytesRead, contentLen - bytesRead);
237:             bytesRead += r;
238:             timeout = millis() + httpTimeout_; // Reset timeout on progress
239:         } else {
240:             delay(1); // Yield to RTOS scheduler
241:         }
242:     }
243: 
244:     http.end();
245: 
246:     if (bytesRead != static_cast<size_t>(contentLen)) {
247:         ESP_LOGE(TAG, "Signature read incomplete — got %u of %d bytes", (unsigned)bytesRead, contentLen);
248:         lastError_ = OTAError::SignatureFetchFailed;
249:         return 0;
250:     }
251: 
252:     ESP_LOGI(TAG, "Signature fetched successfully (%u bytes)", (unsigned)bytesRead);
253:     return bytesRead;
254: }
