65: bool PreconditionEngine::resolveEdges() {
66:     bool ok = true;
67:     for (size_t i = 0; i < count_; ++i) {
68:         auto& p = preconditions_[i];
69:         p.resolvedEdgeCount = 0;
70:         for (uint8_t e = 0; e < p.edgeCount; ++e) {
71:             bool found = false;
72:             for (size_t j = 0; j < count_; ++j) {
73:                 if (strcmp(preconditions_[j].name, p.edges[e].name) == 0) {
74:                     if (p.resolvedEdgeCount < MAX_EDGES_PER_PRECONDITION) {
75:                         p.resolvedEdges[p.resolvedEdgeCount] = static_cast<uint8_t>(j);
76:                         p.resolvedEdgeKinds[p.resolvedEdgeCount] = p.edges[e].kind;
77:                         p.resolvedEdgeCount++;
78:                         found = true;
79:                     }
80:                     break;
81:                 }
82:             }
83:             if (!found) {
84:                 ESP_LOGE(TAG, "Unknown edge name '%s' requested by '%s'", p.edges[e].name, p.name);
85:                 p.resolvedEdgeCount = 0;
86:                 ok = false;
87:                 break;
88:             }
89:         }
90:     }
91: 
92:     if (!ok) return false;
93: 
94:     uint8_t visited[MAX_PRECONDITIONS] = {0};
95:     
96:     auto dfs = [&](auto& self, size_t node) -> bool {
97:         if (visited[node] == 1) return true;
98:         if (visited[node] == 2) return false;
99:         
100:         visited[node] = 1;
101:         const auto& p = preconditions_[node];
102:         for (uint8_t e = 0; e < p.resolvedEdgeCount; ++e) {
103:             if (self(self, p.resolvedEdges[e])) {
104:                 ESP_LOGE(TAG, "Cycle detected involving '%s'", p.name);
105:                 return true;
106:             }
107:         }
108:         visited[node] = 2;
109:         return false;
110:     };
111: 
112:     for (size_t i = 0; i < count_; ++i) {
113:         if (visited[i] == 0) {
114:             if (dfs(dfs, i)) {
115:                 ok = false;
116:             }
117:         }
118:     }
119: 
120:     if (ok) {
121:         for (size_t i = 0; i < count_; ++i) {
122:             const auto& p = preconditions_[i];
123:             if (p.edgeCount == 0) {
124:                 ESP_LOGI(TAG, "Graph: [%s]", p.name);
125:             } else {
126:                 for (uint8_t e = 0; e < p.resolvedEdgeCount; ++e) {
127:                     ESP_LOGI(TAG, "Graph: [%s] -> [%s]", p.name, preconditions_[p.resolvedEdges[e]].name);
128:                 }
129:             }
130:         }
131:     }
132: 
133:     return ok;
