136: void PreconditionEngine::tick(uint32_t nowMs) {
137:     float elapsedSec = 0.0f;
138:     if (lastTickMs_ > 0 && nowMs > lastTickMs_) {
139:         elapsedSec = (nowMs - lastTickMs_) / 1000.0f;
140:     } else if (nowMs < lastTickMs_) {
141:         elapsedSec = 0.0f;
142:     }
143:     lastTickMs_ = nowMs;
144: 
145:     for (size_t i = 0; i < count_; ++i) {
146:         auto& p = preconditions_[i];
147:         
148:         // Step 1: Evaluate the precondition's own function first.
149:         if (p.evaluate) {
150:             p.rawStatus = p.evaluate(p.context);
151:         } else {
152:             p.rawStatus = {false, Cause::InternalError};
153:         }
154: 
155:         // Step 2: Walk edges and overlay dependency constraints.
156:         bool dependencyUnmet = false;
157:         bool bindsToBecameUnmet = false;
158: 
159:         for (uint8_t e = 0; e < p.resolvedEdgeCount; ++e) {
160:             uint8_t idx = p.resolvedEdges[e];
161:             EdgeKind kind = p.resolvedEdgeKinds[e];
162:             const auto& upstream = preconditions_[idx];
163:             
164:             bool upstreamMet = upstream.rawStatus.met;
165:             bool wasMet = p.prevUpstreamMet[e];
166:             p.prevUpstreamMet[e] = upstreamMet;
167:             
168:             if (kind == EdgeKind::Requires || kind == EdgeKind::BindsTo) {
169:                 if (!upstreamMet) {
170:                     dependencyUnmet = true;
171:                 }
172:                 // BindsTo teardown: upstream WAS met last tick but is unmet now
173:                 if (kind == EdgeKind::BindsTo && wasMet && !upstreamMet) {
174:                     bindsToBecameUnmet = true;
175:                 }
176:             }
177:         }
178: 
179:         // Step 3: Override rawStatus based on dependency evaluation.
180:         if (dependencyUnmet) {
181:             p.rawStatus.met = false;
182:             p.rawStatus.cause = Cause::DependencyUnmet;
183:         }
184:         if (bindsToBecameUnmet) {
185:             p.rawStatus.met = false;
186:             p.rawStatus.cause = Cause::DependencyUnmet;
187:         }
188: 
189:         if (p.rawStatus.met) {
190:             p.everMet = true;
191:         }
192: 
193:         p.severity = deriveSeverity(p.rawStatus.cause, p.everMet);
194: 
195:         updateDamping(p, elapsedSec);
196:         updateBreaker(p, nowMs);
197: 
198:         if (p.suppressed) {
199:             p.dampedStatus.met = false;
200:             p.dampedStatus.cause = p.rawStatus.cause;
201:         } else {
202:             p.dampedStatus = p.rawStatus;
203:         }
204:     }
205: }
