207: void PreconditionEngine::updateDamping(PreconditionState& state, float elapsedSec) {
208:     if (!state.everMet) return;
209: 
210:     // Per-precondition override (#154) or engine-wide default
211:     const DampingPolicy& dp = state.dampingOverride ? *state.dampingOverride : dampingPolicy_;
212: 
213:     float weight = 1.0f;
214:     switch (state.severity) {
215:         case Severity::NeedsUser: weight = 5.0f; break;
216:         case Severity::Persistent: weight = 5.0f; break;
217:         case Severity::Transient: weight = 1.0f; break;
218:         case Severity::Blocked: weight = 0.0f; break;
219:         case Severity::Degraded: weight = 1.0f; break;
220:         case Severity::Inactive: weight = 0.0f; break;
221:     }
222: 
223:     if (state.rawStatus.met) {
224:         if (state.penalty > 0.0f && elapsedSec > 0.0f) {
225:             float halfLifeSec = dp.halfLifeMs / 1000.0f;
226:             if (halfLifeSec > 0.0f) {
227:                 state.penalty = state.penalty * std::pow(0.5f, elapsedSec / halfLifeSec);
228:             }
229:         }
230:     } else {
231:         state.penalty += dp.penaltyPerSecond * weight * elapsedSec;
232:     }
233:     
234:     float maxPenalty = dp.suppressThreshold * 2.0f;
235:     if (state.penalty > maxPenalty) {
236:         state.penalty = maxPenalty;
237:     }
238:     
239:     if (!state.suppressed && state.penalty > dp.suppressThreshold) {
240:         state.suppressed = true;
241:     } else if (state.suppressed && state.penalty < dp.reuseThreshold) {
242:         state.suppressed = false;
243:     }
244: }
