246: void PreconditionEngine::updateBreaker(PreconditionState& state, uint32_t nowMs) {
247:     // Per-precondition override (#154) or engine-wide default
248:     const RetryPolicy& rp = state.retryOverride ? *state.retryOverride : retryPolicy_;
249: 
250:     if (state.rawStatus.met) {
251:         state.breaker = BreakerState::Closed;
252:         state.attemptCount = 0;
253:         state.cooldownMs = rp.baseDelayMs;
254:         state.lastAttemptMs = nowMs;
255:         return;
256:     }
257: 
258:     if (state.rawStatus.cause == Cause::DependencyUnmet) {
259:         state.lastAttemptMs = nowMs; // prevent timeouts while blocked
260:         return;
261:     }
262: 
263:     if (state.lastAttemptMs == 0) {
264:         state.lastAttemptMs = nowMs;
265:     }
266: 
267:     if (state.breaker == BreakerState::Closed) {
268:         if (nowMs - state.lastAttemptMs >= state.cooldownMs) {
269:             state.attemptCount++;
270:             state.lastAttemptMs = nowMs;
271:             
272:             if (state.attemptCount >= rp.attemptsBeforeFallback) {
273:                 state.breaker = BreakerState::Open;
274:                 state.cooldownMs = rp.baseDelayMs;
275:             }
276:         }
277:     } else if (state.breaker == BreakerState::Open) {
278:         if (nowMs - state.lastAttemptMs >= state.cooldownMs) {
279:             state.breaker = BreakerState::HalfOpen;
280:             state.lastAttemptMs = nowMs;
281:         }
282:     } else if (state.breaker == BreakerState::HalfOpen) {
283:         if (nowMs - state.lastAttemptMs >= rp.baseDelayMs) {
284:             // Failure in HalfOpen
285:             state.breaker = BreakerState::Open;
286:             state.lastAttemptMs = nowMs;
287:             
288:             uint32_t nextCooldown = state.cooldownMs * 2;
289:             if (nextCooldown > rp.ceilingMs) {
290:                 nextCooldown = rp.ceilingMs;
291:             }
292:             state.cooldownMs = nextCooldown;
293:         }
294:     }
295: }
