77: void ProgressBarWidget::setPercent(int percent, uint32_t durationMs) {
78:     // --- Clamp to valid range ---
79:     if (percent < 0) percent = 0;
80:     if (percent > 100) percent = 100;
81: 
82:     animDurationMs = durationMs;
83: 
84:     if (animDurationMs > 0) {
85:         // --- Initialize Animation Path ---
86:         startPercent = currentPercent;
87:         targetPercent = percent;
88:         animStartTime = 0;   // Will be initialized on first tick()
