101: void ProgressBarWidget::tick(uint32_t currentMillis) {
102:     if (!isVisible) return;
103: 
104:     if (animDurationMs > 0 && currentPercent != targetPercent) {
105:         // --- Lazy init of animation start time ---
106:         // animStartTime is set to 0 in setPercent() and initialized on first tick.
107:         if (animStartTime == 0) {
