111:         uint32_t elapsed = currentMillis - animStartTime;
112:         if (elapsed >= animDurationMs) {
113:             // --- Animation Complete ---
114:             currentPercent = targetPercent;
115:         } else {
116:             // --- Linear Interpolation ---
117:             // progress = elapsed / duration, scaled to the [start, target] range.
118:             // Uses integer math to avoid float on resource-constrained devices.
119:             int range = targetPercent - startPercent;
120:             currentPercent = startPercent + (int)((long)range * (long)elapsed / (long)animDurationMs);
