80: size_t DeviceCrypto::removePKCS7Padding(const uint8_t* buffer, size_t paddedLen) {
81:     if (paddedLen == 0 || paddedLen % 16 != 0) return 0;
82:     uint8_t paddingValue = buffer[paddedLen - 1];
83:     
84:     if (paddingValue == 0 || paddingValue > 16) return 0; // Invalid padding — signal error to caller
85:     
86:     for (size_t i = 0; i < paddingValue; i++) {
87:         if (buffer[paddedLen - 1 - i] != paddingValue) {
88:             return paddedLen;
89:         }
90:     }
91:     return paddedLen - paddingValue;
92: }
